package com.bank.casing;

import java.util.logging.Logger;

// Manual ASCII case normalisation for National Bank of India codes.
public class CaseConverter {
    private static final Logger log = Logger.getLogger(CaseConverter.class.getName());
    private static final int GAP = 32;   // distance between 'a' and 'A' in ASCII

    // Uppercases ASCII letters; leaves digits, spaces, punctuation alone.
    public String toUpperAscii(String s) {
        if (s == null) return null;
        StringBuilder sb = new StringBuilder(s.length());
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c >= 'a' && c <= 'z') {
                sb.append((char) (c - GAP));   // step up to uppercase
            } else {
                sb.append(c);                   // non-lowercase stays as-is
            }
        }
        String out = sb.toString();
        log.fine(() -> "toUpperAscii '" + s + "' -> '" + out + "'");
        return out;
    }

    // Lowercases ASCII letters; leaves everything else alone.
    public String toLowerAscii(String s) {
        if (s == null) return null;
        StringBuilder sb = new StringBuilder(s.length());
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c >= 'A' && c <= 'Z') {
                sb.append((char) (c + GAP));   // step down to lowercase
            } else {
                if (c > 127) {
                    // Non-ASCII: the 32-trick does NOT work correctly here.
                    log.warning(() -> "Non-ASCII char '" + c + "' left unchanged; use Locale-aware method for names");
                }
                sb.append(c);
            }
        }
        String out = sb.toString();
        log.fine(() -> "toLowerAscii -> '" + out + "'");
        return out;
    }
}
