package com.bank.casing;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: normalise account code and display name case.
public class CaseDemo {
    private static final Logger log = Logger.getLogger(CaseDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        CaseConverter converter = new CaseConverter();

        String rajeshCode = "sav2001";          // mixed, normalise to upper
        String priyaName   = "Priya SHARMA";      // normalise to lower

        String upper = converter.toUpperAscii(rajeshCode);
        log.info(() -> "Rajesh code normalised to upper: '" + upper + "'");

        String lower = converter.toLowerAscii(priyaName);
        log.info(() -> "Priya name to lower: '" + lower + "'");
    }
}
